function renderOption(opt, questionId) {
  return `
    <div class="option" id="option-${opt.id}">
      <input type="checkbox" id="${opt.id}" name="${questionId}" value="${opt.id}">
      <label class="option__label" for="${opt.id}">
        <span class="checkbox-box">${CheckIcon()}</span>
        ${opt.label}
      </label>
    </div>`;
}

function renderQuestion(q) {
  const helpHtml = q.help
    ? `<p class="form-field__help">${q.help}</p>`
    : "";

  const optionsHtml = q.options.map((opt) => renderOption(opt, q.id)).join("");

  return `
    <div class="form-field" id="${q.id}">
      <div class="form-field__label">
        <span class="question-number">${q.number}</span>
        <span class="question-text">${q.question}</span>
      </div>
      ${helpHtml}
      <div class="options-grid">${optionsHtml}</div>
    </div>`;
}

function renderQuiz() {
  const app = document.getElementById("quiz-app");

  const questionsHtml = quizData.map(renderQuestion).join(`
