        <span class="result-banner__icon"></span>
        <div class="result-banner__text">
          <strong></strong>
          <span></span>
        </div>
      </div>

      <div class="quiz-divider"></div>

      <div class="quiz-footer">
        <span class="answer-hint">Select all that apply</span>
        <button class="btn-submit" id="submit-btn">
