          <svg viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M3 8H13M13 8L9 4M13 8L9 12" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </button>
      </div>
    </div>`;

  document.getElementById("submit-btn").addEventListener("click", handleSubmit);
}

function handleSubmit() {
  let totalCorrect = 0;

  quizData.forEach((q) => {
    const checked = Array.from(
      document.querySelectorAll(`input[name="${q.id}"]:checked`)
    ).map((el) => el.value);

    const isExactMatch =
      checked.length === q.correct.length &&
      checked.every((v) => q.correct.includes(v));

    if (isExactMatch) totalCorrect++;

    q.options.forEach((opt) => {
      const wrapper = document.getElementById(`option-${opt.id}`);
      wrapper.classList.remove("correct", "incorrect");
      const isChecked = checked.includes(opt.id);
      if (isChecked) {
        wrapper.classList.add(q.correct.includes(opt.id) ? "correct" : "incorrect");
      }
    });
  });

  const banner = document.getElementById("result-banner");
  const icon = banner.querySelector(".result-banner__icon");
  const strong = banner.querySelector("strong");
  const detail = banner.querySelector("span");

  banner.classList.remove("perfect", "good", "retry", "show");

  const total = quizData.length;

  if (totalCorrect === total) {
    banner.classList.add("perfect", "show");
    icon.textContent = "🎉";
    strong.textContent = `Perfect score — ${totalCorrect}/${total}!`;
    detail.textContent = "You nailed every question. Great knowledge of computer languages!";
  } else if (totalCorrect >= Math.ceil(total / 2)) {
    banner.classList.add("good", "show");
    icon.textContent = "👍";
    strong.textContent = `Good job — ${totalCorrect}/${total} correct`;
    detail.textContent = "Review the highlighted answers to see where you can improve.";
  } else {
    banner.classList.add("retry", "show");
    icon.textContent = "📚";
    strong.textContent = `${totalCorrect}/${total} correct — keep studying!`;
    detail.textContent = "Check the highlighted answers and give it another try.";
  }

  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });

  const btn = document.getElementById("submit-btn");
  btn.textContent = "Resubmit";
}

document.addEventListener("DOMContentLoaded", renderQuiz);
