function renderQuiz() {
  const app = document.getElementById("quiz-app");

  const questionsHtml = quizData.map(renderQuestion).join(`
    <div class="quiz-divider"></div>`);

  app.innerHTML = `
    <div class="quiz-header">
      <p class="eyebrow">Knowledge Check</p>
      <h1>Computer Languages Quiz</h1>
      <p class="subtitle">Test your knowledge of programming languages. Select all answers that apply for each question.</p>
